shape.text.set([
  [
    { run: "Revenue", style: { bold: true, color: "#0f172a" } },
    { run: " momentum", style: { color: "#2563eb" } },
  ],
]);
shape.text.style = { fontSize: 44, lineSpacing: 0.92 };
